using System;using UnityEngine;
public static class SourcePartsValidation {
 static void Check(bool condition,string name){if(!condition)throw new Exception("Source-parts golden failed: "+name);}
 public static void Run(){Check(Vector3.Distance(SourcePartsScene.Basis(new Vector3(1,2,3),0),new Vector3(1,2,-3))<1e-6f,"Unity page normal basis");var aligned=SourcePartsScene.Basis(Vector3.right,-27);Check(Mathf.Abs(aligned.x-.8910065f)<1e-6f&&Mathf.Abs(aligned.y+.4539905f)<1e-6f,"hostZ alignment before bounds");var manifest=JsonUtility.FromJson<CatalogManifest>(Resources.Load<TextAsset>("Catalog/manifest").text);Check(manifest.items.Length==81,"preserved71+8");int modes=0;foreach(var item in manifest.items){if(item.animation!="source-parts"||!(item.id.StartsWith("sourceparts-solar-system-")||item.id.StartsWith("sourceparts-arithmetic-")))continue;modes++;var go=new GameObject("Source parts EDITOR SYNTHETIC acceptance");try{var scene=go.AddComponent<CatalogScene>();scene.Configure(item);var parts=go.GetComponent<SourcePartsScene>();Check(parts.pivots.Count==5,"five true identities");Check(!parts.playing&&parts.parameter==0,"reset");bool initial=parts.flat;scene.Spring();Check(parts.flat!=initial,"actual scene left click mode binding");scene.Tap();Check(parts.playing,"actual scene pause binding");scene.ControlAxes(Vector2.zero,Vector2.right,1,"editor-synthetic");Check(parts.parameter==.5f,"actual axes parameter binding");parts.time=2;parts.Sample();Check(parts.label.text.Contains("not learned rig/calibration"),"UI provenance");if(parts.config.topic=="solar-system"){Check(parts.config.parts[4].fallback,"exact blue RGBA not sphere");var sun=parts.Pixel(parts.config.parts[0].centroid[0],parts.config.parts[0].centroid[1]);Check(Vector3.Distance(parts.pivots[0].localPosition,sun)<1e-6f,"fixedSun");for(int i=1;i<5;i++){var original=parts.Pixel(parts.config.parts[i].centroid[0],parts.config.parts[i].centroid[1]);Check(Mathf.Abs(Vector3.Distance(sun,original)-Vector3.Distance(sun,parts.pivots[i].localPosition))<1e-6f,"conserved orbit radius");}}else{parts.parameter=1;parts.Sample();for(int i=0;i<5;i++)Check(parts.config.parts[i].quantity==1,"actual column quantities");Check(parts.pivots[1].localPosition.x<0&&parts.pivots[2].localPosition.x>0,"conserved2+3");Check(parts.config.parts[3].host_z==-27,"selected repair basis");}scene.Reset();Check(!parts.playing&&parts.time==0&&parts.parameter==0,"controller reset");}finally{UnityEngine.Object.DestroyImmediate(go);}}Check(modes==4,"four representations");Debug.Log("SOURCE PARTS GOLDEN PASS: editor-synthetic scene/controller/UI/basis + Sun4 / conserved2+3; physical native acceptance UNVERIFIED");}
}
